python -I - <<'PY'
import glob,json,os
for p in sorted(glob.glob('/app/trajectories/*/capture/trajs.json')):
 print('\n###',p)
 d=json.load(open(p)); lines=d['trajectories']['main_agent'].splitlines()
 for i,l in enumerate(lines):
  e=json.loads(l); c=e.get('message',{}).get('content',[])
  if isinstance(c,str): c=[{'text':c}]
  for x in c:
   if not isinstance(x,dict): continue
   if e['type']=='assistant':
    if 'name' in x:
     a=x.get('input',{}); print(i,'TOOL',x['name'],str(a)[:600])
    elif x.get('text'): print(i,'THOUGHT',x['text'][:500].replace('\n',' '))
   elif e['type']=='user' and x.get('text'): print(i,'USER',x['text'][:1000].replace('\n',' '))
 print('CAPTURES:')
 for q in sorted(glob.glob(os.path.dirname(p)+'/blender_*')):
  cmd=json.load(open(q+'/command.json')); result=json.load(open(q+'/result.json')); print(os.path.basename(q),str(cmd)[:250],str(result)[:180])
PY

