import json,glob,os
for p in sorted(glob.glob('/app/trajectories/*/capture/trajs.json')):
 d=json.load(open(p)); print(os.path.basename(os.path.dirname(os.path.dirname(p))))
 for i,l in enumerate(d['trajectories']['main_agent'].splitlines()):
  e=json.loads(l)
  if e.get('type')=='user':
   c=e.get('message',{}).get('content',[])
   if isinstance(c,str): print(i,c[:3000])
   elif isinstance(c,list):
    for x in c:
     if isinstance(x,dict) and x.get('type')=='text' and 'tool_use_id' not in x: print(i,x.get('text','')[:3000])
